<script>
  import { onDestroy } from "svelte";
  import * as Tone from "tone";

  let hasKey = $state(true);
  let hasSawdust = $state(false);
  let blurStacks = $state(0);
  let highlightedId = $state(null);

  let toneReady = false;
  let sound = null;

  const blurTimers = [];
  const blurTimeSecs = 5;
  const blurAmount = $derived(Math.min(blurStacks * 1.5, 12));

  let currentImageKey = $state("base");
  const imageUrl = $derived(
    `/games/TheJulekalender/TheJulekalenderGameCave__${currentImageKey}.png`
  );

  $effect(() => {
    let stringBuilder = "";

    if (!hasKey) {
      stringBuilder += "no-key__";
    }
    if (hasSawdust) {
      stringBuilder += "sawdust__";
    }
    if (highlightedId) {
      let showHighlight = true;
      if (!hasKey && highlightedId === "key") {
        stringBuilder += "base";
        showHighlight = false;
      } else if (!hasSawdust && highlightedId === "sawdust") {
        stringBuilder += "base";
        showHighlight = false;
      }

      if (showHighlight) {
        stringBuilder += highlightedId + "-highlight";
      }
    } else {
      stringBuilder += "base";
    }

    currentImageKey = stringBuilder;
    console.log(imageUrl);
  });

  function showHighlight(id) {
    highlightedId = id;
  }

  function showBase() {
    highlightedId = null;
  }

  const handleKeyClick = () => {
    if (!hasKey) {
      return;
    }
    hasKey = false;
  };

  const handleBeerClick = () => {
    blurStacks += 1;
    const timer = setTimeout(() => {
      blurStacks = Math.max(0, blurStacks - 1);
    }, blurTimeSecs * 1000);
    blurTimers.push(timer);
  };

  const handleMusicClick = async () => {
    await ensureTone();
    playTune();
  };

  const handleCuttingMachineClick = () => {
    if (hasSawdust) {
      return;
    }
    hasSawdust = true;
  };

  const handleSavdustClick = () => {
    if (!hasSawdust) {
      return;
    }
    hasSawdust = false;
  };

  const handleKeyActivate = (event, action) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      action();
    }
  };

  const ensureTone = async () => {
    if (toneReady) {
      return;
    }

    try {
      await Tone.start();

      sound = new Tone.Player("/games/TheJulekalender/audio/sound.m4a").toDestination();

      Tone.getDestination().volume.value = -6; // dB, try -6 to -18

      toneReady = true;
    } catch (error) {
      console.error("Unable to start Tone.js", error);
    }
  };

  const playTune = () => {
    if (!toneReady || !sound) {
      return;
    }

    Tone.loaded().then(() => {
      sound.start();
    });
  };

  onDestroy(() => {
    blurTimers.forEach((timer) => clearTimeout(timer));
    sound?.dispose();
  });
</script>

